import urls from './urls.js'
import api from './index.js'

const getConfig = function (params) {
  // return出去了一个promise
  return api.post(urls.config, params)
}

const checkLogin = function (params) {
  // return出去了一个promise
  return api.post(urls.login, params)
}

const getHome = function (params) {
  // return出去了一个promise
  return api.post(urls.home, params)
}

const checkPrint = function (params) {
  // return出去了一个promise
  return api.post(urls.hasPrint, params)
}

const getPrint = function (params) {
  // return出去了一个promise
  return api.post(urls.printWork, params)
}

const getPrinterType = function (params) {
  // return出去了一个promise
  var url = urls.printType.replace('nowType', params.nowType)
  delete params.nowType
  return api.post(url, params)
}

export default {
  getConfig,
  checkLogin,
  getHome,
  checkPrint,
  getPrint,
  getPrinterType
}
